#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }
    char *str1 = argv[1];
    char *str2 = argv[2];
    int match = 1;
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    for (int i = 0; i < len1; i++) {
        if (str1[i] == '*') {
            for (int j = i; j < len1; j++) {
                if (str1[j] != '*') {
                    if (str2[i] != str1[j]) {
                        match = 0;
                        break;
                    }
                }
            }
        } else if (str1[i] != str2[i]) {
            match = 0;
            break;
        }
    }
    if (match) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}
